 const task={book:S.book,chapter:S.chapter,idle:false,handle:0,items:null};readerPreparation=task;
 const valid=()=>readerPreparation===task&&!document.hidden&&S.page==='reader'&&S.book===task.book&&S.chapter===task.chapter;
 const queue=(urgent=false)=>{if(window.requestIdleCallback){task.idle=true;task.handle=window.requestIdleCallback(step,{timeout:urgent?80:1200});}else{task.idle=false;task.handle=setTimeout(()=>step(null),urgent?16:32);}};
