  const active=$('#reader-scroll'),build=active?.chapterBuild;
  if(build&&!build.done){if(!deadline||deadline.timeRemaining()>3||deadline.didTimeout)buildChapterSlice(task.chapter,deadline?.didTimeout?1:2,task.book,S.translate,active);queue(true);return;}
