 const chapter=Math.max(0,Math.min(book.position?.chapter||0,book.chapters.length-1)),target=Math.min(book.chapters[chapter].paragraphs.length,Math.max(4,(book.position?.paragraph||0)+4));
 const task={book,chapter,idle:false,handle:0};readerPreparation=task;
 const step=()=>{if(readerPreparation!==task||document.hidden||S.page!=='shelf'||!S.books.includes(book)){return;}if(M.currentOverlay()){readerPreparation=null;return;}buildChapterSlice(chapter,2,book,!!book.translate);const pane=chapterPanes.get(chapterPaneKey(chapter,book,!!book.translate));if(pane?.chapterBuild.next<target)queue();else readerPreparation=null;};
