function savedWordKey(value){return String(value||'').toLowerCase().replace(/’/g,"'");}
function sentenceAnchor(value){if(!value||!['startParagraph','startOffset','endParagraph','endOffset'].every(k=>Number.isSafeInteger(value[k])&&value[k]>=0&&value[k]<=10000000))return undefined;const {startParagraph,startOffset,endParagraph,endOffset}=value;if(endParagraph<startParagraph||endParagraph===startParagraph&&endOffset<=startOffset)return undefined;return {startParagraph,startOffset,endParagraph,endOffset};}
