 for(const original of originals){$$('.saved-sentence',original).forEach(el=>el.replaceWith(...el.childNodes));original.normalize();}const notes=S.notes.filter(n=>n.type==='sentence'&&n.bookId===bookId).flatMap(n=>{const a=n.highlightAnchors?.find(a=>a.chapter===chapter);if(a&&parts){const texts=parts.map(p=>typeof p==='string'?p:p.text),v=a.selection,quote=texts.slice(v.startParagraph,v.endParagraph+1).map((t,i)=>t.slice(i===0?v.startOffset:0,i===v.endParagraph-v.startParagraph?v.endOffset:undefined)).join('\n\n');return [{...n,chapter,selection:v,text:quote}];}return Number(n.chapter)===chapter?[n]:[];});if(!notes.length)return;const annotations=cache?.sentences||savedSentenceRanges(parts?parts.map(p=>typeof p==='string'?p:p.text):originals.map(el=>el.textContent),notes);if(cache)cache.sentences=annotations;const {starts,ranges}=annotations;if(!ranges.length)return;
