/* 0.5.40: per-book drafts, image actions and native PDF handoff. */
let bookEditor=null,bookPress=null,bookPressClick=null,imageSaveSource=null,imageSaving=false;
function validCustomCover(value){return typeof value==='string'&&value.length<800000&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(value);}
function originalBookTitle(book){return bookDisplayTitle({...book,customTitle:null});}
