function pdfPageTitle(page){return tr('第 {page} 页').replace('{page}',String(page+1));}
function updatePdfProgress(){const p=activePdf;if(!p||p.seeking)return;for(const range of [$('#pdf-progress'),$('#pdf-page-range')])if(range)range.value=p.page;updatePdfCounter(p.page);}
function previewPdfPage(page){const p=activePdf;if(!p)return;const old=p.preview??p.page;p.preview=page;p.seeking=true;updatePdfCounter(page);if(old!==page)haptic('segment');}

function syncPdfLayout(){
 if(pdfLayoutFrame)return;pdfLayoutFrame=requestAnimationFrame(()=>{
  pdfLayoutFrame=0;if(!activePdf)return;const root=$('#pdf-chrome'),shown=!!activePdf.ready&&pdfChromeVisible();root?.classList.toggle('pdf-tools-hidden',!shown);for(const [el,edge] of [[$('.pdf-top',root),'top'],[$('.pdf-bottom',root),'bottom']])M.chrome(el,!shown,{edge});M.setInert(root,!shown);
  syncSystemBars();if(!activePdf.ready)return;const regions=shown?[$('.pdf-top'),$('.pdf-directory button'),$('.pdf-progress')].filter(Boolean).map(el=>{const r=el.getBoundingClientRect();return [r.left,r.top,r.right,r.bottom];}):[];
  pdfControl('layout',{sequence:++activePdf.layoutEpoch,animate:!M.reduced(),modal:!!M.currentOverlay(),leadingSpace:pdfLeadingHeight(),edgeHeight:parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--reader-edge-height'))||28,regions}).catch(()=>{});
 });
}
