 sheet(tr(existing?'编辑书签':'添加书签'),`<p class="help">${tr('页码')} ${page+1} / ${activePdf.book.chapters.length}</p><label class="field-label">${tr('书签名称')}<input class="input-field" id="pdf-bookmark-name" maxlength="120" data-page="${page}" data-offset="${existing?.pdfOffset??offset}" data-tag-id="${esc(existing?.id||'')}" value="${esc(existing?.quote||pdfPageTitle(page))}"></label>${existing?`<button class="text-btn" data-action="pdf-bookmark-delete" data-id="${esc(existing.id)}">${tr('删除书签')}</button>`:''}<div class="translation-save">${btn(tr(existing?'保存修改':'添加书签'),'pdf-bookmark-save','bookmark-simple','primary')}</div>`,{panelClass:'pdf-bookmark-sheet'});
