async function pdfNavigate(page,offset=0){if(!activePdf)return;const p=activePdf;p.page=Math.max(0,Math.min(p.book.chapters.length-1,page));p.offset=offset;p.preview=null;p.seeking=false;await pdfControl('go',{page:p.page,offset});await closeOverlay();updatePdfProgress();syncPdfLayout();}
const pdfBaseAction=action;
action=async function(name,el){
 if(!name.startsWith('pdf-'))return pdfBaseAction(name,el);if(!activePdf)return;
 switch(name){
 case 'pdf-back':return exitPdf();
 case 'pdf-toc':S.tocTab='directory';return showPdfToc();
 case 'pdf-jump':return showPdfJump();
 case 'pdf-jump-go':{const value=Number($('#pdf-jump-page')?.value);if(!Number.isInteger(value)||value<1||value>activePdf.book.chapters.length)return toast(tr('请输入有效页码'));return pdfNavigate(value-1);}
 case 'pdf-prev-page':return pdfNavigate(activePdf.page-1);
 case 'pdf-next-page':return pdfNavigate(activePdf.page+1);
 case 'pdf-page':return pdfNavigate(Number(el.dataset.index));
 case 'pdf-bookmark-open':{const t=pdfBookmarks().find(t=>t.id===el.dataset.id);if(t)return pdfNavigate(t.chapter,t.pdfOffset||0);return;}
 case 'pdf-bookmark-edit':{const t=pdfBookmarks().find(t=>t.id===el.dataset.id);if(t)return showPdfBookmark(t.chapter,t.pdfOffset||0);return;}
 case 'pdf-bookmark-delete':await mutateReadingTags(tags=>tags.filter(t=>t.id!==el.dataset.id));await closePanel();if($('#toc-content'))renderTocContent();return syncPdfLayout();
 case 'pdf-bookmark-save':{const input=$('#pdf-bookmark-name');if(!input||input.disabled)return;const quote=input.value.trim();if(!quote)return toast(tr('请输入书签名称'));const bookId=activePdf.book.id,chapter=Number(input.dataset.page),offset=Number(input.dataset.offset)||0,id=input.dataset.tagId||'pdf-tag-'+crypto.randomUUID();input.disabled=true;try{await mutateReadingTags(tags=>[...tags.filter(t=>t.id!==id),{id,bookId,chapter,paragraph:0,offset:0,pdfOffset:offset,quote:quote.slice(0,120),created:Date.now()}]);await closePanel();if($('#toc-content'))renderTocContent();toast(tr('书签已保存'));}finally{input.disabled=false;}return syncPdfLayout();}
 }
};
document.addEventListener('input',e=>{if(activePdf&&['pdf-progress','pdf-page-range'].includes(e.target.id))previewPdfPage(Number(e.target.value));});
document.addEventListener('change',e=>{if(activePdf&&['pdf-progress','pdf-page-range'].includes(e.target.id))pdfNavigate(Number(e.target.value)).catch(err=>toast(err.message));});
