async function loadReaderEdgeStyle(){try{const data=await fetch('assets/reader-edge.json').then(r=>r.json());for(const [i,layer] of data.layers.entries()){const style=document.documentElement.style;style.setProperty('--edge-blur-'+(i+1),layer.blur+'px');style.setProperty('--edge-solid-'+(i+1),layer.solid*100+'%');style.setProperty('--edge-clear-'+(i+1),layer.clear*100+'%');}}catch{}}
function pdfLeadingHeight(){const back=$('.pdf-top [data-action="pdf-back"]');return back?back.offsetTop+back.offsetHeight:56;}

/* Each text book owns its vertical reading mode and horizontal transition. */
let defaultReadingModes=null;
function normalizeReadingModes(value){if(!value||!['continuous','chapter','off'].includes(value.verticalMode)||!['off','slide','fade','curl'].includes(value.horizontalMode))return null;const modes={verticalMode:value.verticalMode,horizontalMode:value.horizontalMode};if(modes.verticalMode==='continuous')modes.horizontalMode='off';if(modes.verticalMode==='off'&&modes.horizontalMode==='off')modes.horizontalMode='curl';return modes;}
function restoreBookReadingModes(book){
 const saved=normalizeReadingModes(book.readingModes),modes=saved||{...(defaultReadingModes||{verticalMode:'chapter',horizontalMode:'curl'})};Object.assign(S.settings,modes);
 if(!saved){book.readingModes={...modes};put('settings',{id:'book-reading-mode:'+book.id,...modes}).catch(()=>toast(tr('阅读模式保存失败')));}
}
async function persistReadingModes(book,modes){
 if(book){await put('settings',{id:'book-reading-mode:'+book.id,...modes});book.readingModes={...modes};}
 else{await put('settings',{...S.settings,...modes,id:'main'});defaultReadingModes={...modes};}
}

