 if(original.length<6)return false;const n=8;if(original.length>=n&&translated.length>=n){const grams=new Set();for(let i=0;i<=original.length-n;i++)grams.add(original.slice(i,i+n).join(' '));for(let i=0;i<=translated.length-n;i++)if(grams.has(translated.slice(i,i+n).join(' ')))return true;}
