 const parts=TransReadTranslation.requests(text,'mymemory',job.source),results=[];
 for(const part of parts){if(!translationJobActive(job))return null;const translated=await translateText(part.text,job);if(translationIncomplete(part.text,translated,job)){const error=Error(tr('译文不完整，请重试或切换翻译服务'));error.code='TRANSLATION_INCOMPLETE';throw error;}results.push(translated);}
